         {:id "state-bound-reduction"
          :properties {:name "4 - the reduction, and the two nets that broke it"
                       :code "import afield.simulation.petri.*

// 4 -- the other half of tonight's work, which is why box 2 exists at all: the STUBBORN
// partial-order reduction. It answers deadlock and refuses everything else, and until
// 2026-08-20 it could answer it *wrongly* on a net with a read or an inhibitor arc, because
// a stubborn set has to be closed under "this transition may disable that one" as well as
// the reverse and only the reverse was implemented.
//
// Both minimal nets are below. Before the fix, the first lost a whole reachable deadlock
// while still agreeing that one existed, and the second called a wedging net deadlock-free.

// A transition consumes a place another only READS. `take` drains `r`; `peek` needs a token
// there and does not consume it, so it was not among the consumers of `r`.
val readArc = petri {
    place("r", tokens = 1); place("s", tokens = 1); place("u", tokens = 1)
    t("take") { from("s"); from("r") }
    t("peek") { read("r"); from("u") }
}

// A transition PRODUCES into a place another INHIBITS on. `push` arms `gate`'s inhibitor by
// filling `x`, and `mayDisable` reads a transition's inputs, so it could not see that.
val inhibitor = petri {
    place("a", tokens = 1); place("g", tokens = 1); place("x")
    t("push") { from("a"); to("x") }
    t("recycle") { from("x"); from("g"); to("a"); to("g") }
    t("gate") { inhibit("x"); from("g") }
}

for ((name, net) in listOf("read arc" to readArc, "inhibitor arc" to inhibitor)) {
    val full = net.stateSpace()
    val reduced = net.stateSpace(reduction = PetriReduction.STUBBORN)
    fun dead(g: PetriStateGraph) = g.deadMarkings.map { g.states[it] }.sortedBy { it.toString() }
    println("$name:")
    println("  full    ${full.stateCount} markings, canDeadlock=${full.canDeadlock}, dead=${dead(full)}")
    println("  reduced ${reduced.stateCount} markings, canDeadlock=${reduced.canDeadlock}, dead=${dead(reduced)}")
    println("  agree on every terminal marking: ${dead(full) == dead(reduced)}")
}

// And the measured claim, on the net the reduction exists for. `exact` is what keeps the two
// searches apart: a completed reduced search has proved deadlock and nothing else.
val big = petri {
    conflict = PetriConflict.ORDER
    grid = cyc(1, 4)
    for (i in 0 until 12) place("fork.$i", tokens = 1)
    for (i in 0 until 12) {
        val left = i
        val right = (i + 1) % 12
        t("grab.$i") { from("fork.$left"); to("holding.$i") }
        t("eat.$i") { from("holding.$i"); from("fork.$right"); to("eating.$i") }
        t("done.$i") { from("eating.$i"); to("fork.$left"); to("fork.$right") }
    }
}
val reduced = big.stateSpace(reduction = PetriReduction.STUBBORN)
println()
println("twelve philosophers, full search:    ${big.stateSpace().outcome} -- it cannot finish")
println("twelve philosophers, reduced search: ${reduced.stateCount} markings, ${reduced.outcome}")
println("  canDeadlock=${reduced.canDeadlock} in ${reduced.deadlockTrace()!!.length} firings")
println("  complete=${reduced.complete} exact=${reduced.exact} bounds=${reduced.bounds}")
"
                       :frame [60.0 2280.0 260.0 56.0]
                       :metadata "tags:
  - petri
  - state-space
  - visualization
description: 4 - the reduction, and the two nets that broke it
"}}]}

